class LRU:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = {}  # insertion order: least recently used -> most recently used

    def get(self, key):
        if key not in self.data:
            return None
        value = self.data.pop(key)
        self.data[key] = value  # present-key get makes it most recently used
        return value

    def put(self, key, value):
        if key in self.data:
            self.data.pop(key)  # updating never removes anything else
        elif len(self.data) >= self.capacity:
            oldest = next(iter(self.data))
            del self.data[oldest]  # evict least recently used first
        self.data[key] = value  # every put makes the key most recently used

    def keys(self):
        return list(self.data)
